# Code generated by Claude
"""The viewer's picture, as plain functions: one implementation of the layout for the live window and the offscreen renderer.

Both src/glfw_viewer.py (the live window, which blits the bitmaps with OpenGL) and src/viewer_composite.py (the offscreen renderer behind
replay's "viewer" video mode, which pastes them into an array) draw the same thing: a follow camera behind the robot base, a status panel with
a key legend at the top left, a row of camera tiles along the bottom edge and, in the live window, a banner bar along the top. This module
holds everything that does not depend on where the pixels go: the follow-camera constants and update, the status panel rows and bitmap, the
banner bitmap and the camera tiles and their positions. Every size is given for the live window's reference height of 960 pixels and
multiplied by `scale` (1.0 for the live window, 1080 / 960 for the 1080-pixel video). Positions are returned with the origin at the top
left; the live window converts them to OpenGL's bottom-left origin.

Nothing here imports MuJoCo's rendering or the graphics library framework (GLFW); the functions need only numpy and OpenCV (the camera
object passed to the follow-camera functions is used only through its attributes).
"""

import math

import cv2
import numpy as np

from src.base_control import base_yaw

CAM_DISTANCE = 3.5      # follow camera: distance behind the base in metres
CAM_ELEVATION = -45     # follow camera: angle above the horizon in degrees (negative = looking down)
FOVY_DEG = 90           # vertical field of view of the follow camera in degrees
REFERENCE_HEIGHT = 960  # the live viewer window is 1280 x 960 pixels; sizes below are for this height
BANNER_HEIGHT = 56      # pixels (at scale 1.0) of the banner bar


def hud_key_list(has_teleop, legend_extra=()):
    """Build the key legend shown under the status panel.

    Args:
        has_teleop (bool): Whether the run has webcam teleoperation. If true,
            the F2 entry (switch the arms between manual and teleoperation) is
            included.
        legend_extra (Sequence[tuple[str, str]]): Further (key, label) entries,
            inserted after the F2 entry and before the F3 entry. Defaults to
            an empty tuple.

    Returns:
        list[tuple[str, str]]: (key cap text, short label) pairs, in display
        order. The fixed entries are the base, arm, pedestal and neck keys,
        F7 and F8 (neck), then F3 (camera images), F4 (snapshot), F5 (log),
        F6 (record video) and Esc (quit).
    """
    return [("Arrows", "drive"), ("Spc", "stop"),
            ("1-8", "L arm +"), ("Q-I", "L arm -"),
            ("A-K", "R arm +"), ("Z-,", "R arm -"),
            ("PgUp/Dn", "pedestal"), ("9 0 - =", "neck +"), ("O P [ ]", "neck -"), ("F7", "frame"), ("F8", "neck home")] + \
        ([("F2", "man/tele")] if has_teleop else []) + \
        list(legend_extra) + \
        [("F3", "cam imgs"), ("F4", "snap"), ("F5", "log"),
         ("F6", "rec video"), ("Esc", "quit")]


def text_bitmap(rows, w, label_w, keys=(), scale=1.0):
    """Draw the status panel as an image.

    The panel has one text row per (label, value) pair, then the key legend:
    each entry is a key cap icon with a short label, laid out left to right
    and wrapped at the panel width so that the legend uses as little height as
    possible. The panel height follows from the number of rows and legend lines.

    Args:
        rows (Sequence[tuple[str, str]]): (label, value) text rows.
        w (int): Panel width in pixels, already multiplied by `scale`.
        label_w (int): Pixel offset of the value column from the left edge,
            already multiplied by `scale`.
        keys (Sequence[tuple[str, str]]): (key, label) legend entries, as
            returned by hud_key_list(). Defaults to an empty tuple (no legend).
        scale (float): Factor applied to every other size (row height, font
            size, line thickness, margins). Defaults to 1.0, which is the live
            viewer.

    Returns:
        numpy.ndarray: Image of shape (height, w, 3), dtype uint8, in
        red-green-blue (RGB) order, top row first.
    """
    S = lambda v: int(round(v * scale))
    line_h, key_h, font = S(20), S(24), cv2.FONT_HERSHEY_SIMPLEX
    fs_row, fs_key, thick = 0.45 * scale, 0.4 * scale, max(1, int(round(scale)))
    layout, x, line = [], S(6), 0
    for key, label in keys:
        kw = cv2.getTextSize(key, font, fs_key, thick)[0][0] + S(8)
        lw = cv2.getTextSize(label, font, fs_key, thick)[0][0]
        if x + kw + S(4) + lw > w - S(6) and x > S(6):
            x, line = S(6), line + 1
        layout.append((key, label, x, line, kw))
        x += kw + S(4) + lw + S(12)
    top = line_h * len(rows) + S(8)
    h = top + (key_h * (line + 1) + S(6) if keys else 0)
    bmp = np.full((h, w, 3), 45, np.uint8)
    for i, (lab, val) in enumerate(rows):
        y = line_h * (i + 1) - S(3)
        cv2.putText(bmp, lab, (S(6), y), font, fs_row, (190, 190, 190), thick, cv2.LINE_AA)
        cv2.putText(bmp, val, (label_w, y), font, fs_row, (255, 255, 255), thick, cv2.LINE_AA)
    if keys:
        cv2.line(bmp, (S(6), top - S(2)), (w - S(6), top - S(2)), (110, 110, 110), thick)
    for key, label, kx, ln, kw in layout:
        y = top + key_h * ln + S(17)
        cv2.rectangle(bmp, (kx, y - S(14)), (kx + kw, y + S(4)), (80, 80, 80), -1)
        cv2.rectangle(bmp, (kx, y - S(14)), (kx + kw, y + S(4)), (200, 200, 200), thick)
        cv2.putText(bmp, key, (kx + S(4), y), font, fs_key, (255, 255, 255), thick, cv2.LINE_AA)
        cv2.putText(bmp, label, (kx + kw + S(4), y), font, fs_key, (150, 220, 150), thick, cv2.LINE_AA)
    return bmp


def setup_follow_camera(cam):
    """Sets the follow camera's fixed distance and elevation and its starting azimuth.

    Args:
        cam (mujoco.MjvCamera): A free camera, already given its defaults by mujoco.mjv_defaultCamera(). Its distance, elevation and azimuth
            are set to CAM_DISTANCE, CAM_ELEVATION and 90 degrees.
    """
    cam.distance, cam.elevation, cam.azimuth = CAM_DISTANCE, CAM_ELEVATION, 90


def update_follow_camera(cam, data, body_id):
    """Points the follow camera at the base and turns it to look along the base's heading.

    Args:
        cam (mujoco.MjvCamera): The free follow camera. Its lookat point and azimuth are written.
        data (mujoco.MjData): Simulation state; the base position is data.xpos[body_id] and the heading comes from base_control.base_yaw().
        body_id (int): Id of the body to follow ("base_link").

    Returns:
        float: The base's yaw in degrees (the camera's azimuth is this plus 90).
    """
    cam.lookat[:] = data.xpos[body_id]
    yaw_deg = math.degrees(base_yaw(data))
    cam.azimuth = yaw_deg + 90
    return yaw_deg


def hud_rows(time_s, base_vel, yaw_deg, position, middle_rows=(), status=None, mode=None, neck_deg=None, extra_rows=()):
    """Builds the rows of the status panel.

    The first six rows (time, speed, velocity, yaw rate, yaw, position) are the same everywhere. The middle rows are the ones that differ
    between the live window (frame time, keyboard command, recording state) and the video (video rate, applied twist). Then come the episode
    status, the controller mode, the neck angles and any extra rows (the live window's arms row).

    Args:
        time_s (float): Simulation time in seconds.
        base_vel (tuple[float, float, float]): World-frame base velocity (vx, vy in metres per second, wz in radians per second).
        yaw_deg (float): Base yaw in degrees.
        position (Sequence[float]): Base x, y, z in metres.
        middle_rows (Sequence[tuple[str, str]]): (label, value) rows for the backend-specific part. Defaults to none.
        status (str | None): Episode status text for the "episode" row; no row if empty or None. Defaults to None.
        mode (str | None): "auto" or "teleop" for the "controller" row; no row if None. Defaults to None.
        neck_deg (Sequence[float] | None): The four neck joint angles in degrees for the neck row; no row if None or empty. Defaults to None.
        extra_rows (Sequence[tuple[str, str]]): Rows appended at the end. Defaults to none.

    Returns:
        list[tuple[str, str]]: (label, value) rows in display order.
    """
    vx, vy, wz = base_vel
    rows = [("sim time", f"{time_s:.2f} s"),
            ("base speed (m/s)", f"{math.hypot(vx, vy):.2f}"),
            ("base vx, vy (m/s)", f"{vx:+.2f}, {vy:+.2f}"),
            ("yaw rate (rad/s)", f"{wz:+.2f}"),
            ("yaw (deg)", f"{yaw_deg:+.1f}"),
            ("position x, y, z (m)", f"{position[0]:.2f}, {position[1]:.2f}, {position[2]:.3f}")]
    rows += list(middle_rows)
    if status:
        rows.append(("episode", status))
    if mode:
        rows.append(("controller", mode.upper()))
    if neck_deg:
        rows.append(("neck pan,lift,elb,wrist", ", ".join(f"{v:+.0f}" for v in neck_deg)))
    return rows + list(extra_rows)


def hud_bitmap(rows, keys, scale=1.0):
    """Draws the status panel (rows and key legend) as a bitmap of the standard width.

    Args:
        rows (list[tuple[str, str]]): (label, value) rows, from hud_rows().
        keys (list[tuple[str, str]]): Key legend entries, from hud_key_list().
        scale (float): Size factor relative to the live window. Defaults to 1.0.

    Returns:
        numpy.ndarray: RGB bitmap of shape (height, round(400 * scale), 3), dtype uint8.
    """
    return text_bitmap(rows, int(round(400 * scale)), int(round(180 * scale)), keys, scale)


def hud_position(scale=1.0, banner_height=0):
    """Gives where the status panel's top-left corner goes, below the banner if there is one.

    Args:
        scale (float): Size factor relative to the live window. Defaults to 1.0.
        banner_height (int): Height in pixels of the banner above the panel. Defaults to 0.

    Returns:
        tuple[int, int]: (left, top) in pixels, origin at the top left.
    """
    margin = int(round(8 * scale))
    return margin, margin + banner_height


def banner_bitmap(text, kind, width):
    """Draws the full-width banner bar: red for a policy request nobody has answered, blue while the operator has control.

    The text is centred and its font is shrunk, down to a limit, until it fits the width.

    Args:
        text (str): The banner text.
        kind (str): "needed" (red bar) or any other value (blue bar).
        width (int): Frame width in pixels.

    Returns:
        numpy.ndarray: RGB bitmap of shape (BANNER_HEIGHT, width, 3), dtype uint8.
    """
    scale = 0.9
    while cv2.getTextSize(text, cv2.FONT_HERSHEY_DUPLEX, scale, 2)[0][0] > width - 40 and scale > 0.4:
        scale -= 0.05
    bar = np.full((BANNER_HEIGHT, width, 3), (200, 30, 30) if kind == "needed" else (30, 90, 200), np.uint8)
    tw, th = cv2.getTextSize(text, cv2.FONT_HERSHEY_DUPLEX, scale, 2)[0]
    cv2.putText(bar, text, ((width - tw) // 2, (BANNER_HEIGHT + th) // 2), cv2.FONT_HERSHEY_DUPLEX, scale, (255, 255, 255), 2, cv2.LINE_AA)
    return bar


def inset_layout(width, n_tiles, scale=1.0):
    """Gives the size and horizontal positions of the row of camera tiles along the bottom edge.

    Each tile is at most 320 x 240 pixels (times `scale`), shrunk to fit the frame width; the row sits one gap above the bottom edge.

    Args:
        width (int): Frame width in pixels.
        n_tiles (int): Number of tiles in the row.
        scale (float): Size factor relative to the live window. Defaults to 1.0.

    Returns:
        tuple[int, int, int, list[int]]: Tile width, tile height, gap (also the distance from the bottom edge), and the left x of each tile, in
        pixels.
    """
    gap = int(round(8 * scale))
    iw = min(int(round(320 * scale)), (width - gap * (n_tiles + 1)) // n_tiles)
    ih = iw * 3 // 4
    return iw, ih, gap, [gap + k * (iw + gap) for k in range(n_tiles)]


def inset_tile(name, img, iw, ih, scale=1.0):
    """Draws one camera tile: the image scaled to the tile size, with its name in a dark box in the top-left corner.

    Args:
        name (str): The camera's name, written in the corner.
        img (numpy.ndarray | None): RGB image of the camera, any size, row 0 on top; None draws a dark grey tile (no frame delivered yet).
        iw (int): Tile width in pixels.
        ih (int): Tile height in pixels.
        scale (float): Size factor relative to the live window, for the label. Defaults to 1.0.

    Returns:
        numpy.ndarray: RGB bitmap of shape (ih, iw, 3), dtype uint8.
    """
    S = lambda v: int(round(v * scale))
    if img is None:
        small = np.full((ih, iw, 3), 40, np.uint8)
    else:
        small = cv2.resize(img, (iw, ih), interpolation=cv2.INTER_AREA)
    cv2.rectangle(small, (0, 0), (S(len(name) * 9 + 10), S(20)), (45, 45, 45), -1)
    cv2.putText(small, name, (S(5), S(15)), cv2.FONT_HERSHEY_SIMPLEX, 0.5 * scale, (255, 255, 255), max(1, int(round(scale))), cv2.LINE_AA)
    return small
